import{_ as a,o as i,c as p,a2 as n}from"./chunks/framework.D66Xq0Kv.js";const k=JSON.parse('{"title":"swap 交换内存","description":"","frontmatter":{},"headers":[],"relativePath":"system-config/swap.md","filePath":"system-config/swap.md","lastUpdated":1792000532000}'),e={name:"system-config/swap.md"};function t(l,s,h,d,o,c){return i(),p("div",null,[...s[0]||(s[0]=[n(`<h1 id="swap-交换内存" tabindex="-1">swap 交换内存 <a class="header-anchor" href="#swap-交换内存" aria-label="Permalink to &quot;swap 交换内存&quot;">​</a></h1><p>swap 有两种主要形式：<strong>swap 文件</strong> 和 <strong>swap 分区</strong>。</p><p>查看当前已启用的 swap：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>swapon -s</span></span>
<span class="line"><span>swapon --show</span></span></code></pre></div><p>关闭 swap：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>swapoff xxxx</span></span></code></pre></div><h2 id="启用-swap-分区" tabindex="-1">启用 swap 分区 <a class="header-anchor" href="#启用-swap-分区" aria-label="Permalink to &quot;启用 swap 分区&quot;">​</a></h2><p>提前创建好 sda2 为 swap 分区：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkswap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/sda2</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swapon</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/sda2</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 编辑 fstab</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/dev/sda2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> none</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> swap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> defaults</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span></span></code></pre></div><h2 id="创建-swap-文件" tabindex="-1">创建 swap 文件 <a class="header-anchor" href="#创建-swap-文件" aria-label="Permalink to &quot;创建 swap 文件&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 用三种方法创建都可以</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> if=/dev/zero</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> of=/swapfile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bs=1M</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> count=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2048</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fallocate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 2G</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /swapfile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkswap</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -U</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clear</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --size</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 2G</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /swapfile</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 修改文件权限，避免其他用户误触</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 600</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /swapfile</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 格式化为 swap 文件</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkswap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /swapfile</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 启动 swap 文件</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swapon</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /swapfile</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 添加到 fstab</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/swapfile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> none</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> swap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> defaults</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span></span></code></pre></div><h2 id="配置-swappiness" tabindex="-1">配置 swappiness <a class="header-anchor" href="#配置-swappiness" aria-label="Permalink to &quot;配置 swappiness&quot;">​</a></h2><p>swappiness 数字越大，越积极的把较少使用的匿名内存交换到 swap。</p><p>查看当前值（默认一般是 60）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cat /proc/sys/vm/swappiness</span></span></code></pre></div><p>服务器低延迟或 PC 桌面建议调低，尽可能使用物理内存，一般默认即可。</p><h3 id="临时设置" tabindex="-1">临时设置 <a class="header-anchor" href="#临时设置" aria-label="Permalink to &quot;临时设置&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo sysctl -w vm.swappiness=100</span></span></code></pre></div><h3 id="永久设置" tabindex="-1">永久设置 <a class="header-anchor" href="#永久设置" aria-label="Permalink to &quot;永久设置&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tee</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/sysctl.d/99-swappiness.conf</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;EOF&#39;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">vm.swappiness=100</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">EOF</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sysctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --system</span></span></code></pre></div><h2 id="zram-和-zswap" tabindex="-1">zram 和 zswap <a class="header-anchor" href="#zram-和-zswap" aria-label="Permalink to &quot;zram 和 zswap&quot;">​</a></h2><ul><li><strong>zram</strong>：在内存里压缩数据，<code>/dev/zram0</code></li><li><strong>zswap</strong>：在硬盘 swap 之前创建一个压缩缓冲</li></ul><p>查看当前 swap 实时状态：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vmstat 1</span></span></code></pre></div><h3 id="zram" tabindex="-1">zram <a class="header-anchor" href="#zram" aria-label="Permalink to &quot;zram&quot;">​</a></h3><p>安装 <code>systemd-zram-generator</code>，创建或编辑 <code>/etc/systemd/zram-generator.conf</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[zram0]</span></span>
<span class="line"><span>zram-size = min(ram / 2, 4096)</span></span>
<span class="line"><span>compression-algorithm = zstd</span></span>
<span class="line"><span>swap-priority = 100</span></span></code></pre></div><blockquote><p>内存的一半，但不会超过 4G</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[zram0]</span></span>
<span class="line"><span>zram-size = ram / 2</span></span>
<span class="line"><span>compression-algorithm = zstd</span></span>
<span class="line"><span>swap-priority = 100</span></span></code></pre></div><blockquote><p>内存的一半</p></blockquote><p>重启后验证：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>swapon --show</span></span>
<span class="line"><span>zramctl</span></span>
<span class="line"><span>free -h</span></span></code></pre></div><h3 id="zswap-swapfile" tabindex="-1">zswap + swapfile <a class="header-anchor" href="#zswap-swapfile" aria-label="Permalink to &quot;zswap + swapfile&quot;">​</a></h3><p>先确认 swapfile 已启用 <code>swapon --show</code>，再添加内核参数到 GRUB（<code>/etc/default/grub</code> 的 <code>GRUB_CMDLINE_LINUX=&quot;...&quot;</code>）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>zswap.enabled=1 zswap.compressor=zstd zswap.zpool=zsmalloc zswap.max_pool_percent=20</span></span></code></pre></div><h4 id="debian-系列" tabindex="-1">Debian 系列 <a class="header-anchor" href="#debian-系列" aria-label="Permalink to &quot;Debian 系列&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>update-grub</span></span></code></pre></div><h4 id="red-hat-系列" tabindex="-1">Red Hat 系列 <a class="header-anchor" href="#red-hat-系列" aria-label="Permalink to &quot;Red Hat 系列&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>grubby --update-kernel=ALL --args=&quot;zswap.enabled=1 zswap.compressor=zstd zswap.zpool=zsmalloc zswap.max_pool_percent=20&quot;</span></span></code></pre></div><p>查看默认内核启动项：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>grubby --info=DEFAULT</span></span></code></pre></div><p>删除：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>grubby --update-kernel=ALL --remove-args=&quot;zswap.enabled zswap.compressor zswap.zpool zswap.max_pool_percent&quot;</span></span></code></pre></div><p>重启后检查：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cat /proc/cmdline</span></span>
<span class="line"><span>cat /sys/module/zswap/parameters/enabled</span></span>
<span class="line"><span>cat /sys/module/zswap/parameters/compressor</span></span>
<span class="line"><span>cat /sys/module/zswap/parameters/zpool</span></span>
<span class="line"><span>cat /sys/module/zswap/parameters/max_pool_percent</span></span></code></pre></div>`,45)])])}const g=a(e,[["render",t]]);export{k as __pageData,g as default};
